{
  // テスト規約を止める。plugins を 2 つの override の両方に書き、domains / services の override をこの後ろに置く理由は .claude/hooks/README.md（#1445 の項）
  "files": ["src/**/*.{ts,tsx,mts,cts}"],
  "plugins": ["jest"],
  "rules": {
    "jest/no-restricted-jest-methods": ["error", {
      "mock": "vi.mock / vi.doMock でモジュールを丸ごと差し替えない。差し替えてよいのは libs/ が包む外部 I/O だけで、そのときもフェイクを渡す（rules/testing.md「モックは原則使わない」）",
      "doMock": "vi.mock / vi.doMock でモジュールを丸ごと差し替えない。差し替えてよいのは libs/ が包む外部 I/O だけで、そのときもフェイクを渡す（rules/testing.md「モックは原則使わない」）"
    }],
    "jest/no-hooks": ["error", { "allow": ["afterEach"] }],
    // jest プラグインが warn で入れる correctness 規則のうち、これだけを外す。理由は .claude/hooks/README.md（#1445 の項）
    "jest/require-to-throw-message": "off"
  }
